import { Readable } from 'node:stream';
async function main(): Promise<void> {
  const a: any = [Buffer.from('a')];
  console.log(a);
  console.log(a[0]);
  const o: any = { b: Buffer.from('hi'), n: 1, nested: { c: Buffer.alloc(3) } };
  console.log(o);
  console.log([Buffer.alloc(52, 1)]);
  const r = new Readable({ read() {} });
  const p: any = r.toArray();
  setTimeout(() => { r.push('z'); r.push(null); }, 5);
  const v: any = await p;
  console.log(v, v[0]);
}
